allocation = {team: 0 for team in headcounts}
for _ in range(desks):
    # max() returns the first maximal element, so fully tied teams
    # resolve to the one listed first. Fraction keeps quotients exact.
    best = max(
        allocation,
        key=lambda team: (Fraction(headcounts[team], allocation[team] + 1),
                          headcounts[team]),
    )
    allocation[best] += 1
return allocation
